  /**
   * @method
   * @name apex#fetchMyTrades
   * @description fetches information on multiple orders made by the user
   * *classic accounts only*
   * @see
   * https://api-docs.omni.apex.exchange/#privateapi-v3-for-omni-get-trade-history
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve,
   * default 100
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {object} [params.until] end time
   * @param {boolean} [params.side] BUY or SELL
   * @param {string} [params.orderType] "LIMIT", "MARKET","STOP_LIMIT",
   * "STOP_MARKET", "TAKE_PROFIT_LIMIT","TAKE_PROFIT_MARKET"
   * @param {boolean} [params.page] Page numbers start from 0
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("beginTimeInclusive"),
                              since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any endTimeExclusive = this->safeIntegerN(
                     params, ccxt::list{std::string("endTime"),
                                        std::string("endTimeExclusive"),
                                        std::string("until")});
                 if (isTrue(!isEqual(endTimeExclusive, std::any{}))) {
                   ::setValue(request, std::string("endTimeExclusive"),
                              endTimeExclusive);
                   params = this->omit(
                       params, ccxt::list{std::string("endTime"),
                                          std::string("endTimeExclusive"),
                                          std::string("until")});
                 }
                 std::any response = awaitValue(
                     this->privateGetV3Fills(this->extend(request, params)));
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any orders =
                     this->safeList(data, std::string("orders"), ccxt::list{});
                 return this->parseTrades(orders, market, since, limit);
               })
        .share();
  }

